    <el-alert v-if="capabilities.collection_only" title="联调模式仅采集已绑定资产；SSH 主机身份、认证、采集结果与 CVE 适用性分别记录，不执行扫描或修复。" type="info" :closable="false" />
    <el-tabs v-model="tab">
      <el-tab-pane label="设备连接" name="connections">
        <section class="operation-section"><div class="section-head"><div><h2>OpenWrt / Ubuntu 只读采集</h2><p>采集前校验 SSH 主机指纹；支持 ED25519 密钥引用与历史密码认证。</p></div><el-button type="primary" :disabled="!canOperate" @click="editConnection()">登记连接</el-button></div>
          <DataTable :rows="connections"><el-table-column prop="label" label="设备名称" min-width="140" /><el-table-column label="管理地址" min-width="150"><template #default="{ row }">{{ row.host }}:{{ row.port }}</template></el-table-column><el-table-column label="接入状态" min-width="130"><template #default="{ row }">{{ !row.enabled ? '已禁用' : row.asset_id ? (row.identity_verified ? (row.identity_source === 'authenticated_collection_node' ? '节点本机身份已确认' : '已采集并绑定') : '已关联，待身份核验') : '待确认身份' }}</template></el-table-column><el-table-column label="认证方式" min-width="130"><template #default="{ row }">{{ row.auth_type === "ssh_key" ? "ED25519 密钥" : "密码认证" }}</template></el-table-column><el-table-column label="认证引用" min-width="210"><template #default="{ row }">{{ row.auth_type === "ssh_key" ? row.key_path_env : row.credential_env }}</template></el-table-column><el-table-column label="操作" width="370"><template #default="{ row }"><el-button size="small" :disabled="!canOperate" @click="checkConnection(row)">配置检查</el-button><el-button size="small" :disabled="!canOperate || !row.enabled || !row.asset_id || busy !== null || busyRun !== null" :loading="busy === row.id" @click="collect(row)">采集</el-button><el-button size="small" :disabled="!canOperate" @click="editConnection(row)">编辑</el-button><el-button size="small" :disabled="!row.asset_id" @click="router.push({ path: '/device-tasks', query: { asset: row.asset_id } })">设备任务</el-button></template></el-table-column></DataTable>
          <el-empty v-if="!connections.length" description="先登记一台 OpenWrt 网关，或导入只读采集结果" />
        </section>
      </el-tab-pane>
      <el-tab-pane label="采集记录" name="collection-runs">
        <section class="operation-section"><h2>采集任务记录</h2><p>记录来自后端任务；配置检查不会连接设备，采集成功也不代表 CVE 已确认。</p>
          <DataTable :rows="collectionRuns">
            <el-table-column label="任务 / 原始证据 / Trace" min-width="220"><template #default="{ row }">{{ row.id }}<small class="cell-sub">{{ row.result?.inventory_evidence_id || '尚无本轮原始证据' }}</small><small class="cell-sub">{{ row.trace_id || '历史任务无 Trace' }}</small></template></el-table-column>
            <el-table-column label="执行状态" min-width="120"><template #default="{ row }">{{ collectionStatus(row.status) }}</template></el-table-column>
