        <section class="operation-section"><h2>Ubuntu 官方核验与历史纠正</h2><p>查询或获取 Canonical 原始记录；发行版状态优先于 NVD 上游范围，旧影子结果保留。</p>
          <el-input v-model="officialCve" placeholder="输入 CVE 编号" aria-label="官方核验 CVE" style="max-width: 280px" />
          <el-button :loading="officialBusy" @click="inspectOfficial(false)">查询核验记录</el-button><el-button :disabled="!canOperate" :loading="officialBusy" @click="inspectOfficial(true)">获取官方记录并复核</el-button>
          <el-alert v-for="c in officialData.corrections" :key="c.id" :title="'纠正 #' + c.id + ' / 资产 ' + c.asset_id + ' / 历史风险 ' + c.risk_id + '：' + c.before.match_status + ' → ' + c.after.match_status + '；' + c.reason" type="warning" :closable="false" />
          <table v-if="officialData.records.length" class="data-table"><thead><tr><th>原始证据</th><th>来源状态 / 获取时间</th><th>SHA256</th></tr></thead><tbody><tr v-for="record in officialData.records" :key="record.evidence_id"><td><a :href="record.source_url" target="_blank" rel="noopener noreferrer">{{ record.evidence_id }}</a></td><td>{{ record.evidence_status }} / {{ record.fetched_at }}<p>{{ record.error }}</p></td><td>{{ record.content_sha256 }}</td></tr></tbody></table>
        </section>
        <section class="operation-section"><div class="section-head"><div><h2>OpenWrt 厂商版本依据</h2><p>根据官方公告人工核对固件与组件版本；未匹配的版本保留待确认。</p></div><el-button :disabled="!canOperate" @click="editAdvisory()">登记公告依据</el-button></div>
          <DataTable :rows="advisories"><el-table-column prop="cve_id" label="CVE" min-width="150" /><el-table-column prop="package_name" label="组件" min-width="140" /><el-table-column prop="release" label="适用固件" min-width="120" /><el-table-column label="受影响版本" min-width="160"><template #default="{ row }">{{ row.affected_versions.join('、') }}</template></el-table-column><el-table-column label="已修复版本" min-width="160"><template #default="{ row }">{{ row.fixed_versions.join('、') }}</template></el-table-column><el-table-column label="操作" width="160"><template #default="{ row }"><a :href="row.source_url" target="_blank" rel="noopener noreferrer">官方来源</a><el-button text :disabled="!canOperate" @click="editAdvisory(row)">编辑</el-button></template></el-table-column></DataTable>
          <el-empty v-if="!advisories.length" description="尚无适用性依据；不会套用 Ubuntu 修复版本" />
        </section>
      </el-tab-pane>
    </el-tabs>
    <el-dialog v-model="connectionDialog" :title="editingId ? '编辑设备连接' : '登记设备连接'" width="min(600px, 94vw)"><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-form label-position="top" @submit.prevent="save"><div class="upgrade-form-grid"><el-form-item label="设备名称"><el-input aria-label="设备名称" v-model="connectionForm.label" /></el-form-item><el-form-item label="管理 IP" required><el-input aria-label="管理 IP" v-model="connectionForm.host" /></el-form-item><el-form-item label="SSH 端口"><el-input-number v-model="connectionForm.port" :min="1" :max="65535" /></el-form-item><el-form-item label="SSH 用户名"><el-input aria-label="SSH 用户名" v-model="connectionForm.username" /></el-form-item></div><el-form-item label="认证方式"><el-select v-model="connectionForm.auth_type" aria-label="认证方式"><el-option label="ED25519 密钥" value="ssh_key" /><el-option label="密码认证（历史兼容）" value="password" :disabled="capabilities.collection_only" /></el-select></el-form-item><el-form-item :label="capabilities.collection_only ? '关联已有资产（必选）' : '关联已有资产（可选）'" :required="capabilities.collection_only"><el-select v-model="connectionForm.asset_id" aria-label="关联已有资产" clearable :disabled="Boolean(editingId && connectionForm.asset_id)"><el-option v-for="asset in openwrtAssets" :key="asset.id" :label="asset.hostname" :value="asset.id" /></el-select></el-form-item><el-form-item v-if="connectionForm.auth_type === 'ssh_key'" label="采集节点私钥路径变量名称" required><el-input aria-label="采集节点私钥路径变量名称" v-model="connectionForm.key_path_env" placeholder="LINUXGUARD_DEVICE_ 开头，变量值为 Linux 采集节点本地私钥路径" /></el-form-item><el-form-item v-if="connectionForm.auth_type === 'ssh_key'" label="私钥口令变量名称（可选）"><el-input aria-label="私钥口令变量名称" v-model="connectionForm.key_passphrase_env" placeholder="加密私钥的后端口令变量；未加密则留空" /></el-form-item><el-form-item v-if="connectionForm.auth_type === 'password'" label="后端凭据变量名称" required><el-input aria-label="后端凭据变量名称" v-model="connectionForm.credential_env" placeholder="LINUXGUARD_DEVICE_ 开头的专用变量" /></el-form-item><el-form-item label="SSH 主机 SHA256 指纹" required><el-input aria-label="SSH 主机 SHA256 指纹" v-model="connectionForm.host_key_sha256" placeholder="SHA256:…" /></el-form-item><el-switch v-model="connectionForm.enabled" active-text="启用连接" /><div class="upgrade-actions"><el-button @click="connectionDialog = false">取消</el-button><el-button native-type="submit" type="primary" :loading="saving">保存连接</el-button></div></el-form></el-dialog>
    <el-dialog v-model="advisoryDialog" title="登记官方公告依据" width="min(680px, 94vw)"><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-form label-position="top" @submit.prevent="saveAdvisory"><div class="upgrade-form-grid"><el-form-item label="CVE 编号" required><el-input v-model="advisoryForm.cve_id" /></el-form-item><el-form-item label="软件包名称" required><el-input v-model="advisoryForm.package_name" /></el-form-item></div><el-form-item label="适用 OpenWrt 完整固件版本" required><el-input v-model="advisoryForm.release" /></el-form-item><el-form-item label="受影响组件完整版本（逗号分隔）" required><el-input v-model="advisoryForm.affected" /></el-form-item><el-form-item label="已修复组件完整版本（逗号分隔）" required><el-input v-model="advisoryForm.fixed" /></el-form-item><el-form-item label="OpenWrt 官方 HTTPS 公告地址" required><el-input v-model="advisoryForm.source_url" /></el-form-item><el-form-item label="核对说明"><el-input v-model="advisoryForm.notes" type="textarea" /></el-form-item><p class="operation-help">平台保存人工整理的依据，不会把提供链接当作已自动验证公告内容。</p><div class="upgrade-actions"><el-button @click="advisoryDialog = false">取消</el-button><el-button native-type="submit" type="primary" :loading="saving">保存依据</el-button></div></el-form></el-dialog>
  </section>
</template>
<script setup>
import { computed, onMounted, reactive, ref, watch } from "vue";
import { useRouter } from "vue-router";
import { ElMessage } from "element-plus";
import DataTable from "../components/DataTable.vue";
import DeviceControlToken from "../components/DeviceControlToken.vue";
import { api, fetchAssets, uploadAsset } from "../api";
import { controlSession, errorMessage, fetchDeviceCapabilities, fetchConnections, fetchObservations, fetchOpenWrtAdvisories, saveConnection, discoverDevices, saveOpenWrtAdvisory, preflightConnection, fetchCollectionRuns, createCollectionRun, executeCollectionRun, fetchCollectionRun } from "../api/deviceOperations";
const openwrtAssets = ref([]);
const router = useRouter(); const tab = ref("connections"); const loading = ref(false); const error = ref(""); const capabilities = ref({}); const connections = ref([]); const observations = ref([]); const advisories = ref([]);
const busy = ref(null); const scanning = ref(false); const saving = ref(false); const connectionDialog = ref(false); const advisoryDialog = ref(false); const editingId = ref(null); const formError = ref("");
const collectionRuns = ref([]); const busyRun = ref(null);
const officialCve = ref(""); const officialBusy = ref(false); const officialData = ref({ records: [], corrections: [] });
async function inspectOfficial(refresh) {
  const cve = officialCve.value.trim().toUpperCase();
  if (!/^CVE-\d{4}-\d{4,}$/.test(cve)) { error.value = "请输入有效 CVE 编号"; return; }
  officialBusy.value = true; error.value = "";
  try {
    if (refresh) await api.post("/vulnerabilities/official/verify", { cve_ids: [cve] });
    officialData.value = (await api.get("/vulnerabilities/official/records", { params: { cve_id: cve } })).data;
    if (!officialData.value.records.length) ElMessage.info("尚无该 CVE 的官方核验记录");
  } catch (e) { error.value = errorMessage(e); }
  finally { officialBusy.value = false; }
}
const canOperate = computed(() => Boolean(controlSession.token && capabilities.value.control_configured));
const connectionForm = reactive({ asset_id: null, label: "", host: "", port: 22, username: "root", auth_type: "ssh_key", credential_env: "", key_path_env: "", key_passphrase_env: "", host_key_sha256: "", enabled: true });
const scanForm = reactive({ cidr: "", ports: "22,80,443,1883,8883" });
const advisoryForm = reactive({ cve_id: "", package_name: "", release: "", affected: "", fixed: "", source_url: "", notes: "" });
const formatTime = value => value ? new Date(value).toLocaleString("zh-CN") : "—";
const presenceText = value => ({ responded: "探测时有响应", lease_record: "有租约，在线未确认", expired_lease: "已过期租约" }[value] || "待确认");
async function load() { loading.value = true; error.value = ""; try { capabilities.value = await fetchDeviceCapabilities(); if (capabilities.value.collection_only && !controlSession.token) { connections.value = []; collectionRuns.value = []; return; } [connections.value, observations.value, advisories.value, openwrtAssets.value, collectionRuns.value] = await Promise.all([fetchConnections(), fetchObservations(), fetchOpenWrtAdvisories(), fetchAssets().then(rows => rows.filter(a => ["openwrt", "ubuntu"].includes(a.distribution))), controlSession.token ? fetchCollectionRuns() : Promise.resolve([])]); } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
function editConnection(row) { editingId.value = row?.id || null; Object.assign(connectionForm, { asset_id: row?.asset_id || null, auth_type: row ? (row.auth_type || "password") : "ssh_key", key_path_env: row?.key_path_env || "", key_passphrase_env: row?.key_passphrase_env || "", label: row?.label || "", host: row?.host || "", port: row?.port || 22, username: row?.username || "root", credential_env: row?.credential_env || "", host_key_sha256: row?.host_key_sha256 || "", enabled: row?.enabled ?? true }); formError.value = ""; connectionDialog.value = true; }
async function save() { if (capabilities.value.collection_only && !connectionForm.asset_id) { formError.value = "联调模式须选择已有 OpenWrt 资产"; return; } saving.value = true; formError.value = ""; try { await saveConnection({ ...connectionForm, asset_id: connectionForm.asset_id || null, credential_env: connectionForm.auth_type === "password" ? connectionForm.credential_env : "", key_path_env: connectionForm.auth_type === "ssh_key" ? connectionForm.key_path_env : "", key_passphrase_env: connectionForm.auth_type === "ssh_key" ? connectionForm.key_passphrase_env : "" }, editingId.value); connectionDialog.value = false; ElMessage.success("连接已登记，下一步采集确认设备身份"); await load(); } catch (e) { formError.value = errorMessage(e); } finally { saving.value = false; } }
const collectionStatus = value => ({ pending: '待执行', queued_remote: '已转交采集节点', running: '执行中', completed: '采集完成', failed: '采集失败', interrupted: '执行中断', cancelled: '已取消' }[value] || '未记录');
const evidenceStatus = value => ({ not_applicable: '不适用（节点本机采集）', not_attempted: '未尝试', verified: '已校验', unverified: '未核验', succeeded: '成功', failed: '失败', pending: '待执行', running: '进行中', queued_remote: '已转交采集节点', running_remote: '采集节点执行中', interrupted: '中断', unknown: '未知' }[value] || '未记录');
async function executeRun(row) { busyRun.value = row.id; error.value = ""; let outcome; let requestError = ''; try { outcome = await executeCollectionRun(row.id); } catch (e) { requestError = errorMessage(e); try { outcome = await fetchCollectionRun(row.id); } catch { /* Query only; never replay SSH. */ } } finally { busyRun.value = null; } await load(); if (outcome?.status === 'completed') ElMessage.success('已更新已有资产：' + outcome.result.package_count + ' 条软件包；CVE 本次未评估'); else if (outcome?.status === 'queued_remote') ElMessage.info('本机不执行设备 SSH：任务已转交登记的 Linux 采集节点（' + (outcome.result?.queued_for_node || '等待领取') + '），请稍后刷新采集记录'); else error.value = outcome?.error || requestError || '任务尚未完成，请查询采集记录；不会自动重试'; }
async function collect(row) { busy.value = row.id; error.value = ""; try { const run = await createCollectionRun(row.id, crypto.randomUUID()); collectionRuns.value = [run, ...collectionRuns.value.filter(x => x.id !== run.id)]; await executeRun(run); } catch (e) { error.value = errorMessage(e); } finally { busy.value = null; } }
const checkLabels = { asset_bound: '已有资产关联', connection_enabled: '连接启用', host_fingerprint_configured: '主机指纹配置', authorized_target: '目标授权范围', collector_available: '采集脚本部署', node_platform: 'Ubuntu/Linux 执行节点', remote_node_configured: '远程采集节点登记', node_identity_configured: '节点标识', authentication_reference_configured: '本地认证引用', key_path_metadata: '密钥路径元数据', passphrase_reference_configured: '密钥口令引用' };
async function checkConnection(row) { error.value = ""; try { const result = await preflightConnection(row.id); if (result.ready) ElMessage.success(result.checks.node_platform ? '本地配置检查通过；未连接设备、未加载私钥' : '配置检查通过：本机不执行设备 SSH，采集将由登记的 Linux 采集节点执行；未连接设备、未加载私钥'); else error.value = '配置检查未通过：' + Object.entries(result.checks).filter(([, ok]) => !ok).map(([name]) => checkLabels[name] || '配置项').join('、') + '；未连接设备'; } catch (e) { error.value = errorMessage(e); } }
async function scan() { scanning.value = true; error.value = ""; try { const ports = scanForm.ports.split(/[,，]/).map(x => Number(x.trim())); const result = await discoverDevices({ cidr: scanForm.cidr.trim(), ports }); ElMessage.success("发现 " + result.responding_devices + " 个有响应地址"); await load(); } catch (e) { error.value = errorMessage(e); } finally { scanning.value = false; } }
async function importInventory(file) { if (!file.raw) return; if (file.raw.size > 5_000_000) { error.value = "采集文件不能超过 5 MB"; return; } try { const result = await uploadAsset(file.raw); if (result.asset.inventory_complete) ElMessage.success("已导入 " + result.package_parse_stats.parsed_count + " 条软件包记录"); else ElMessage.warning("清单不完整，已保留上次软件包记录，请复核采集状态"); await load(); } catch (e) { error.value = errorMessage(e); } }
function editAdvisory(row) { Object.assign(advisoryForm, { cve_id: row?.cve_id || "", package_name: row?.package_name || "", release: row?.release || "", affected: row?.affected_versions?.join(",") || "", fixed: row?.fixed_versions?.join(",") || "", source_url: row?.source_url || "", notes: row?.notes || "" }); formError.value = ""; advisoryDialog.value = true; }
async function saveAdvisory() { saving.value = true; formError.value = ""; try { const { affected, fixed, ...rest } = advisoryForm; await saveOpenWrtAdvisory({ ...rest, affected_versions: affected.split(/[,，]/).map(x => x.trim()).filter(Boolean), fixed_versions: fixed.split(/[,，]/).map(x => x.trim()).filter(Boolean) }); advisoryDialog.value = false; ElMessage.success("依据已保存，请在风险中心重新执行匹配"); await load(); } catch (e) { formError.value = errorMessage(e); } finally { saving.value = false; } }
onMounted(load);
watch(() => controlSession.token, load);
</script>

